-- The card collection shown in the UI's sport tabs. photo_id names the card's photos in the photo
-- bucket, photos/<photo_id>/front.jpg and back.jpg (scripts\upload-card-photos.ps1): the PSA cert
-- number, or order-<order>-r<row> when PSA's file names carry none. Grades are as on the PSA label.
-- Re-running updates the listed cards to these values.

CREATE TABLE IF NOT EXISTS ${schema}.cards (
    id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    photo_id    varchar(64)  NOT NULL UNIQUE,
    cert_number varchar(20)  UNIQUE,
    sport       varchar(20)  NOT NULL CHECK (sport IN ('Baseball', 'Basketball', 'Football', 'Hockey')),
    year        integer      NOT NULL,
    set_name    varchar(255) NOT NULL,
    card_number varchar(20)  NOT NULL,
    player      varchar(255) NOT NULL,
    variety     varchar(255),
    grade       varchar(20)
);

ON CONFLICT (photo_id) DO UPDATE SET
    cert_number = EXCLUDED.cert_number, sport = EXCLUDED.sport, year = EXCLUDED.year,
    set_name = EXCLUDED.set_name, card_number = EXCLUDED.card_number, player = EXCLUDED.player,
    variety = EXCLUDED.variety, grade = EXCLUDED.grade;
